import{_ as r,C as o,c as l,o as n,aj as s,G as t,w as p}from"./chunks/framework.Bfdr4H5E.js";const w=JSON.parse('{"title":"For Those Who Perceive It As Too Complex","description":"","frontmatter":{"outline":"deep","prev":{"text":"For Those Concerned That It Appears Too Simple","link":"/trading-with-pav/for-those-concerned-that-it-appears-too-simple"},"next":{"text":"Take Action & Wrap Up","link":"/trading-with-pav/take-action-wrap-up"}},"headers":[],"relativePath":"trading-with-pav/for-those-who-perceive-it-as-too-complex.md","filePath":"trading-with-pav/for-those-who-perceive-it-as-too-complex.md"}'),c={name:"trading-with-pav/for-those-who-perceive-it-as-too-complex.md"};function h(m,e,d,u,f,v){const a=o("GraphComment"),i=o("ClientOnly");return n(),l("div",null,[e[0]||(e[0]=s('<h1 id="for-those-who-perceive-it-as-too-complex" tabindex="-1">For Those Who Perceive It As Too Complex <a class="header-anchor" href="#for-those-who-perceive-it-as-too-complex" aria-label="Permalink to &quot;For Those Who Perceive It As Too Complex&quot;">​</a></h1><p>This article is for For Those Who Perceive It As Too Complex.</p><p>I expect many of you will be overwhelmed by the size of the task ahead of you. Don’t be!</p><p>Do all you can to enjoy the process, and you’ll get there in time.</p><p>I also expect many of you will have difficulty trading live, with the amount of detail within the procedures manual. Please note… this level of complexity will not be required for long.</p><p>Any complexity you perceive is a result of my having to try to explain these largely intuitive and subjective processes. Take the procedures and use them for now. In time you’ll be able to simplify them.</p><div class="warning custom-block"><p class="custom-block-title">In time you&#39;ll be able to see</p><ul><li>The reality of this game is that, unless we’re trading longer timeframes, we won’t have time to refer to such detailed and comprehensive procedural steps.</li><li>With a small amount of experience, I expect you’ll be able to operate effectively with a short checklist, with each step referred to by a single statement (one or two words).</li><li>You may even eventually have the whole process internalized, allowing you to operate without reference to any procedures manual.</li></ul></div><p>Put aside any concerns about complexity – they’ll disappear as you gain experience. Enjoy the process; and take action.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',9)),t(i,null,{default:p(()=>[t(a)]),_:1})])}const x=r(c,[["render",h]]);export{w as __pageData,x as default};
